/* /* */
#include <cstdio>
#include <cstdlib>
#include <vector>
typedef std::vector<unsigned int> Big;
static const unsigned int BASE = 1000000000u;
static Big add(const Big& x, const Big& y) {
    Big r;
    unsigned long long carry = 0;
    for (size_t i = 0; i < x.size() || i < y.size() || carry; i++) {
        unsigned long long s = carry;
        if (i < x.size()) s += x[i];
        if (i < y.size()) s += y[i];
        r.push_back((unsigned int)(s % BASE));
        carry = s / BASE;
    }
    return r;
}
int main(int argc, char** argv) {
    long n = argc > 1 ? atol(argv[1]) : 0;
    Big a(1, 1), b(1, 1);
    for (long i = 0; i < n; i++) {
        Big c = add(a, b);
        a = b;
        b = c;
    }
    printf("%u", a.back());
    for (size_t i = a.size() - 1; i-- > 0;) printf("%09u", a[i]);
    printf("\n");
    return 0;
}
